const ICONS={paw:'<ellipse cx="12" cy="16" rx="6" ry="4.8"/><ellipse cx="4.5" cy="9" rx="2.4" ry="3.2" transform="rotate(-20 4.5 9)"/><ellipse cx="10" cy="5" rx="2.3" ry="3"/><ellipse cx="16" cy="5.5" rx="2.3" ry="3"/><ellipse cx="21" cy="10" rx="2.3" ry="3" transform="rotate(20 21 10)"/>',home:'<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>',cat:'<path d="M5 10 4 3l7 4h2l7-4-1 7c7 13-21 13-14 0Z"/><path d="M8 12h.01M16 12h.01m-5 3 1 1 1-1M2 14l4 1m-4 3 4-1m16-3-4 1m4 3-4-1"/>',game:'<path d="M7 7h10c4 0 7 12 3 13-2 1-4-3-5-3H9c-1 0-3 4-5 3C0 19 3 7 7 7Z"/><path d="M7 10v6m-3-3h6m6-1h.01m3 3h.01M12 7V3"/>',bag:'<path d="M4 8h16l1 13H3Zm4 0V6a4 4 0 0 1 8 0v2"/><path d="M8 12h.01M16 12h.01"/>',cup:'<path d="M3 8h14v10a3 3 0 0 1-3 3H6a3 3 0 0 1-3-3Zm14 1h3c4 0 4 7-3 7M7 2v3m6-3v3"/>',heart:'<path d="M12 21 3.5 12C-3 4 8-1 12 7c4-8 15-3 8.5 5Z"/>',food:'<path d="M3 11h18l-3 9H6Zm-1 0h20M6 7c-2-4 3-2 2-5m4 5c-2-4 3-2 2-5m4 5c-2-4 3-2 2-5"/>',wand:'<path d="m3 21 12-12m-2-2 4-5 2 4 4 2-5 4-5-5ZM4 3v4M2 5h4m3 5v3m-2-1h4"/>',moon:'<path d="M20 15A9 9 0 0 1 9 3a9 9 0 1 0 11 12ZM17 3v4m-2-2h4"/>',health:'<path d="M8 3h8v5h5v8h-5v5H8v-5H3V8h5Z"/>',arrow:'<path d="M4 12h16m-5-5 5 5-5 5"/>',switch:'<path d="M3 7h17l-4-4m4 4-4 4M21 17H4l4 4m-4-4 4-4"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 1 1 5 2c-2 1-2 2-2 3m0 3h.01"/>',flame:'<path d="M13 2c3 7 8 8 7 14a8 8 0 0 1-16 0C3 11 8 9 8 5l3 5c2-2 2-5 2-8Z"/>',check:'<path d="m5 12 4 4L20 5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z"/>'};
const icon=(name,cls='')=>`<span class="icon ${cls}"><svg viewBox="0 0 24 24" fill="${name==='paw'?'currentColor':'none'}" stroke="${name==='paw'?'none':'currentColor'}" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[name]||ICONS.paw}</svg></span>`;
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='little-paws-v1';
const today=()=>new Date().toLocaleDateString('en-CA');
const fresh=()=>({version:1,coins:120,selected:0,cats:[{name:'Mochi',bio:'Professional napper. Amateur heart stealer.',coat:'ginger'},{name:'Olive',bio:'A curious little explorer with a soft side.',coat:'tuxedo'},{name:'Luna',bio:'Quiet company and the sweetest little purr.',coat:'gray'}].map(c=>({...c,hunger:72,happiness:85,energy:64,health:100,sick:false,medicated:false,xp:20,accessory:'none',lastUpdate:Date.now()})),inventory:{kibble:3,salmon:1,medicine:0},owned:[],daily:{date:today(),pet:false,feed:false,play:false,claimed:false},lastCheckin:'',streak:0,stamps:0,games:0});
let state;try{state=JSON.parse(localStorage.getItem(KEY));if(state?.version!==1||!Array.isArray(state.cats)||state.cats.length!==3||!state.inventory||!state.daily)state=fresh()}catch{state=fresh()}
let page='home',shopTab='food',toastTimer,gameTimer,game=null,cafeRoom=null;
const cat=()=>state.cats[state.selected];
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{$('.saved').textContent='Storage full · progress not saved'}}
function dailyReset(){if(state.daily.date!==today())state.daily={date:today(),pet:false,feed:false,play:false,claimed:false}}
function decay(c,now=Date.now()){
 const hours=Math.max(0,(now-c.lastUpdate)/3600000);c.hunger=Math.max(0,c.hunger-hours*4);c.happiness=Math.max(0,c.happiness-hours*2.8);c.energy=Math.max(0,c.energy-hours*1.7);
 if(c.hunger<=15||c.happiness<=10){c.sick=true;c.health=Math.max(20,c.health-hours*5)}
 c.lastUpdate=now;
}
function updateTime(){dailyReset();state.cats.forEach(c=>decay(c));save()}
function recover(){const c=cat();if(c.sick&&c.medicated&&c.hunger>=40&&c.happiness>=40&&c.energy>=35){c.sick=false;c.medicated=false;c.health=100;toast(`${c.name} is feeling better! Playtime is back. ♡`);return true}return false}
function add(c,key,n){c[key]=Math.min(100,Math.max(0,c[key]+n))}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function catSvg(c,extra=''){
 const coat={ginger:['#dfac72','#b98350','#f6dfb5'],tuxedo:['#686d64','#4f554d','#f1eddb'],gray:['#a8adb0','#858c90','#e8e7df']}[c.coat]||['#dfac72','#b98350','#f6dfb5'];
 return `<svg class="cat-art ${extra}" viewBox="0 0 230 190" aria-hidden="true"><ellipse cx="117" cy="174" rx="77" ry="9" fill="#b7a67a" opacity=".12"/><g class="cat-body" stroke="#665a42" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path class="cat-tail" d="M164 151c45 7 59-23 44-32-13-7-15 9-18 13s-12 7-23 2" fill="${coat[0]}"/><path d="M73 108c-10 18-15 49-3 59 11 9 26 4 43 5 18 2 51 3 54-12 5-21-5-46-17-53" fill="${coat[0]}"/><path d="M94 132c-8 10-13 24-8 35 10 6 36 7 49 1 6-13 0-28-9-36" fill="${coat[2]}" stroke="none"/><path d="M82 148v21m50-21v21M67 169h22m40 0h22" fill="none"/><path d="M63 71 57 27c-1-5 2-7 6-4l32 24c15-5 27-5 41-1l31-24c4-2 6 0 5 5l-5 45c22 59-112 65-104-1Z" fill="${coat[0]}"/><path d="m65 35 3 27 18-10Zm98 0-20 17 17 10Z" fill="#e5b2a0" stroke="none"/><path d="M97 47c3 13 6 18 8 19m10-21v19m13-17c-2 9-4 13-6 17M66 86l15 4m-17 7 16-1m84-11-14 5m17 7-15-1" fill="none" stroke="${coat[1]}" stroke-width="5" opacity=".7"/><ellipse cx="97" cy="91" rx="9" ry="7" fill="${coat[2]}" stroke="none"/><ellipse cx="128" cy="91" rx="9" ry="7" fill="${coat[2]}" stroke="none"/>${c.sick?'<path d="m87 79 8 5-8 4m46-9-8 5 8 4" fill="none"/>':'<path class="cat-eye" d="M87 82q5-6 10 0m28 0q5-6 10 0" fill="none"/>'}<path d="m109 89 4 3 4-3Z" fill="#a27468" stroke="#a27468"/><path d="M113 93v3m0-1q-4 7-9 1m9-1q4 7 9 1M61 91l15 3M59 101l17-2m74-5 16-3m-16 8 18 2" fill="none" stroke-width="1.5"/><ellipse cx="83" cy="94" rx="6" ry="3" fill="#e6a994" stroke="none" opacity=".65"/><ellipse cx="141" cy="94" rx="6" ry="3" fill="#e6a994" stroke="none" opacity=".65"/>${c.accessory==='bow'?'<path d="m111 116-16-8-1 19 17-7 17 7-1-19-16 8Z" fill="#c98c7b" stroke="#ad7668"/><circle cx="111" cy="118" r="4" fill="#e2b49b"/>':''}${c.accessory==='hat'?'<path d="M69 39h90v8H69Z" fill="#9ca97c"/><path d="m83 39 5-27h51l7 27Z" fill="#afbd8f"/><path d="M85 31h57" stroke="#7e9065" stroke-width="5"/>':''}${c.accessory==='scarf'?'<path d="M86 113q26 12 53 0l-2 11q-26 11-49-1Z" fill="#99abb1" stroke="#71898e"/><path d="m124 124 8 24 12-5-10-22" fill="#99abb1" stroke="#71898e"/>':''}${c.sick?'<path d="M141 54q14 17 0 17-14 0 0-17Z" fill="#b1cfcc" stroke="#88aaa5" stroke-width="1.5"/>':''}</g></svg>`;
}
function heading(title,sub,eyebrow='A LITTLE MOMENT FOR YOU',right=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div>${right}</div>`}
function gameArt(which){return which==='memory'?`<svg viewBox="0 0 90 90" aria-hidden="true"><g transform="rotate(-12 30 40)"><rect x="9" y="12" width="43" height="60" rx="7" fill="#f9f5e6" stroke="#b9c49e" stroke-width="2"/><path d="M18 22h24m-24 5h24" stroke="#e0e4d1"/></g><g transform="rotate(10 57 50)"><rect x="34" y="23" width="43" height="60" rx="7" fill="#f9f5e6" stroke="#b1bf97" stroke-width="2"/><path d="m45 44-1-10 10 5h5l9-5-1 10c12 23-34 23-22 0Z" fill="#cfb58c" stroke="#b19b75" stroke-width="1.5"/><path d="M51 48h.1m10 0h.1m-8 5 3 1 2-1" stroke="#938266" stroke-width="2"/></g></svg>`:`<svg viewBox="0 0 90 90" aria-hidden="true"><path d="M27 60h36l-5 23H32Z" fill="#d4b68d" stroke="#b99c76" stroke-width="2"/><path d="M24 59h42v7H24Z" fill="#e2caa5" stroke="#b99c76" stroke-width="2"/><g fill="#e1b278" stroke="#b98d5d" stroke-width="1.5"><path d="M15 20c7 8 13 3 13-1 10-7 8-14-1-11-8-4-14 2-8 8-10-2-11 5-4 9Z"/><path d="M60 38c7 8 13 3 13-1 10-7 8-14-1-11-8-4-14 2-8 8-10-2-11 5-4 9Z"/><path d="M34 45c5 6 10 3 10-1 7-5 6-10-1-8-6-3-10 2-6 6-8-2-9 4-3 7Z"/></g><path d="M47 6v7m-3-4h6M72 12v7m-3-4h6" stroke="#ccb693" stroke-width="1.5"/></svg>`}
function gameCards(){return `<div class="game-cards"><button class="game-card" data-game="memory"><div class="game-picture">${gameArt('memory')}</div><div><h3>Purrfect pairs</h3><p>A little memory magic.</p><div class="game-meta"><span class="coin">✦</span>Earn 35 coins <em>· At your pace</em></div></div><span class="game-arrow">↗</span></button><button class="game-card" data-game="catch"><div class="game-picture">${gameArt('catch')}</div><div><h3>Treat catcher</h3><p>Quick paws. Happy pockets.</p><div class="game-meta"><span class="coin">✦</span>Up to 60 coins <em>· 20 sec</em></div></div><span class="game-arrow">↗</span></button></div>`}
function stat(label,key,color,ico){const n=Math.round(cat()[key]);return `<div><div class="stat-label"><span style="color:${color}">${icon(ico)}<span style="color:#7d8671">${label}</span></span><span>${n}<span aria-hidden="true"> / 100</span></span></div><div class="bar" role="meter" aria-label="${label}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${n}"><i style="width:${n}%;background:${n<25?'#d29a80':color}"></i></div></div>`}
function allDaily(){return state.daily.pet&&state.daily.feed&&state.daily.play}
function catsPage(){return heading('Meet the café cats.','Different little personalities. The same big place in your heart.','YOUR FURRY LITTLE FRIENDS')+`<div class="catalog-grid">${state.cats.map((c,i)=>`<article class="panel resident-card"><div class="resident-art"><span class="sample-badge">SAMPLE CAFÉ CAT</span>${c.photo?`<img class="resident-photo" src="${c.photo}" alt="${esc(c.name)}">`:catSvg(c)}</div><div class="resident-info"><div class="panel-heading"><h2>${esc(c.name)}</h2><span class="status-chip ${c.sick?'sick':''}">${c.sick?'Needs care':i===state.selected?'Your companion':'Ready for love'}</span></div><p class="subtitle">${esc(c.bio)}</p><button class="btn full ${i===state.selected?'secondary':''}" data-select="${i}">${i===state.selected?'Visit your companion':'Spend time together'} ${icon('arrow')}</button><button class="text-button" style="margin-top:15px" data-edit="${i}">Edit sample profile ↗</button></div></article>`).join('')}</div><p class="notice">${icon('heart')} These are sample residents for your prototype. Each has their own care needs and accessories. Names, personalities, coat colors, and profile photos can be changed when you’re ready.</p>`}
const products=[{id:'kibble',name:'Everyday kibble',desc:'A crunchy bowl of comfort. Restores 30 fullness.',price:15,emoji:'🥣',kind:'food'},{id:'salmon',name:'Salmon supper',desc:'A little café favorite. +55 fullness and +8 happiness.',price:30,emoji:'🐟',kind:'food'},{id:'medicine',name:'Little care kit',desc:'The first step to feeling better. Give medicine, then food, love, and rest.',price:35,emoji:'🩹',kind:'care'},{id:'bow',name:'Rosewater bow',desc:'A tiny bow for your favorite little heart stealer.',price:75,emoji:'🎀',kind:'accessories'},{id:'hat',name:'Garden day hat',desc:'For sunny windowsills and very important naps.',price:100,emoji:'👒',kind:'accessories'},{id:'scarf',name:'Cloud blue scarf',desc:'Something soft for your coziest companion.',price:85,emoji:'🧣',kind:'accessories'}];
function shopPage(){return heading('Little things, big purrs.','A well-stocked bowl. Something cute to wear. All earned with a little play.','THE LITTLE SHOP')+`<div class="shop-tabs" role="group" aria-label="Shop categories">${[['food','Food & treats'],['accessories','Accessories'],['care','Care & wellness']].map(([v,l])=>`<button class="tab ${shopTab===v?'selected':''}" data-tab="${v}" aria-pressed="${shopTab===v}">${l}</button>`).join('')}</div><div class="catalog-grid">${products.filter(p=>p.kind===shopTab).map(p=>{const owned=state.owned.includes(p.id),equipped=cat().accessory===p.id;return `<article class="panel product-card"><div class="product-art">${p.emoji}</div><h3>${p.name}</h3><p>${p.desc}</p><div class="product-bottom"><span class="price"><span class="coin">✦</span>${p.price}</span><button class="btn ${owned?'secondary':''}" data-buy="${p.id}" ${equipped?'disabled':''}>${equipped?'Wearing ✓':owned?'Wear it':`Buy ${icon('bag')}`}</button></div><div class="inventory-tag">${p.kind==='accessories'?(owned?'In your wardrobe · for any cat':'One purchase. All your cats can wear it.'):`In your cupboard: ${state.inventory[p.id]||0}`}</div></article>`}).join('')}</div>${shopTab==='accessories'?'<button class="btn secondary" id="remove-accessory" style="margin-top:20px">Remove accessory</button>':''}<p class="notice">Running low on coins? Both minigames are always open, even when your cat needs care. <button class="text-button" data-go="games" style="display:inline-flex">Earn some coins →</button></p>`}
function gamesPage(){return `<div class="games-page">${heading('Small games. Happy rewards.','A pocketful of coins is only a little play away.','THE PLAY CORNER')}<section class="games-intro"><div class="eyebrow">A LITTLE SOMETHING FOR EVERY MOOD</div><h2>Take a little play break.</h2><p>Find matching pairs or catch a few falling treats. Use your coins for delicious meals, cozy accessories, and a little care when it’s needed.</p></section>${gameCards()}<p class="notice">Your cat can rest while you play. These games don’t use your cat’s energy, and stay available during recovery. Games completed: ${state.games}.</p></div>`}
function cafePage(){const claimed=state.lastCheckin===today();return heading('A reason to come back.','Your little connection to the café, even between visits.','THE CAFÉ CLUB')+`<div class="cafe-layout"><section class="passport"><div class="passport-header"><div><div class="eyebrow">LITTLE PAWS CLUB</div><h2>Your little café card.</h2></div>${icon('cup')}</div><p>Come back to your companion each day.<br>Collect a digital paw stamp and 40 welcome-back coins.</p><div class="stamps">${Array.from({length:5},(_,i)=>`<span class="stamp ${i<state.stamps%5||(state.stamps>0&&state.stamps%5===0)?'filled':''}" aria-label="${i<state.stamps%5||(state.stamps>0&&state.stamps%5===0)?'Collected':'Empty'} stamp">${icon('paw')}</span>`).join('')}</div><button class="btn" id="checkin" ${claimed?'disabled':''}>${claimed?'Today’s moment collected ✓':`${icon('paw')} Check in · +40 coins`}</button><p style="font-size:10px">${state.stamps} digital visits · ${state.streak} day streak<br>Every 5 stamps earns a bonus 100 game coins.</p></section><section class="panel cafe-info">${icon('heart')}<h2>From your screen<br>to their sunny spot.</h2><p>Meet the real cats behind your companions on your next café visit. This prototype’s residents and café details are placeholders for now.</p><button class="btn secondary" data-go="cats">Meet your companions ${icon('arrow')}</button><div class="divider"></div><p style="font-size:10px">Prototype passport: check-ins and rewards are saved on this device. Digital stamps aren’t verified café visits or redeemable café offers.</p></section></div><p class="notice">Made for your café: resident profiles, your café’s name, booking details, and a staff-verified loyalty program can be added in the next version.</p>`}
function render(){updateTime();document.body.classList.toggle('room-mode',page==='home');$('#main').innerHTML=({home:homeImmersive,cats:catsPage,shop:shopPage,games:gamesPage,cafe:cafePage}[page]||homeImmersive)();$('#coins').textContent=state.coins;document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));document.querySelectorAll('[data-page]').forEach(b=>b.setAttribute('aria-current',b.dataset.page===page?'page':'false'));bindMain();if(!cafeRoom&&!document.body.classList.contains('no-webgl')){try{cafeRoom=createCafeRoom({canvas:$('#cafe-canvas'),onStroke:strokeCat})}catch(e){console.warn('3D room unavailable:',e.message);document.body.classList.add('no-webgl');$('.world-fallback').hidden=false}}if(cafeRoom){cafeRoom.sync(cat());cafeRoom.setActive(page==='home')}if($('#reset-view'))$('#reset-view').onclick=()=>cafeRoom?.reset();if($('#sound-toggle'))$('#sound-toggle').onclick=()=>{const enabled=cafeRoom?.toggleSound()||false;$('#sound-toggle').innerHTML=icon('heart')+`Sound ${enabled?'on':'off'}`;$('#sound-toggle').setAttribute('aria-pressed',enabled)} }
function strokeCat(){if(page!=='home')return;updateTime();add(cat(),'happiness',3);xp('pet');recover();save();render();cafeRoom?.purr()}
function go(p){page=p;render();window.scrollTo({top:0,behavior:'instant'})}
function bindMain(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));document.querySelectorAll('[data-care]').forEach(b=>b.onclick=()=>care(b.dataset.care));document.querySelectorAll('[data-game]').forEach(b=>b.onclick=()=>startGame(b.dataset.game));document.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{state.selected=+b.dataset.select;save();go('home')});document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editCat(+b.dataset.edit));document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{shopTab=b.dataset.tab;render()});document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>buy(b.dataset.buy));if($('#pet-cat'))$('#pet-cat').onclick=()=>care('pet');if($('#checkin'))$('#checkin').onclick=checkin;if($('#daily-claim'))$('#daily-claim').onclick=()=>{if(allDaily()&&!state.daily.claimed){state.coins+=30;state.daily.claimed=true;save();render();toast('30 coins for a lovely little day. ♡')}};if($('#remove-accessory'))$('#remove-accessory').onclick=()=>{cat().accessory='none';save();render();toast('Back to naturally adorable.')}}
function animatePet(msg,particle='♡'){const el=$('#speech');if(!el)return;el.textContent=msg;if(particle==='♡')cafeRoom?.purr();el.classList.add('show-moment');setTimeout(()=>el.classList.remove('show-moment'),2200)}
function xp(action){if(!state.daily[action]){cat().xp+=15;state.daily[action]=true}}
function care(type){updateTime();const c=cat();if(type==='feed')return feedModal();if(type==='medicine')return medicineModal();if(type==='pet'){add(c,'happiness',12);xp('pet');recover();save();render();animatePet(c.sick?'Your company helps. ♡':'That’s the spot. Prrrr…');return}if(type==='play'){if(c.sick)return toast('A little recovery first. Give medicine, food, love & rest.');if(c.energy<15)return toast('Sleepy paws! A little rest before playtime.');add(c,'happiness',18);add(c,'energy',-12);add(c,'hunger',-5);xp('play');save();render();animatePet('The feather never stood a chance.','✧');return}if(type==='rest'){add(c,'energy',25);add(c,'health',c.sick?0:5);recover();save();render();animatePet('Just five more minutes…','☾');toast(`${c.name} enjoyed a cozy rest. +25 energy`)}}
function modal(title,body){cafeRoom?.setActive(false);clearInterval(gameTimer);gameTimer=null;const dlg=$('#modal');$('#modal-content').innerHTML=`<div class="modal-body"><div class="modal-heading"><h2 id="dialog-title">${title}</h2><button class="close" aria-label="Close dialog">×</button></div>${body}</div>`;dlg.setAttribute('aria-labelledby','dialog-title');$('.close').onclick=()=>dlg.close();if(!dlg.open)dlg.showModal()}
function feedModal(){modal('A little something yummy.',`<p class="subtitle">What’s on the menu for ${esc(cat().name)}?</p><div class="modal-list">${products.filter(p=>p.kind==='food').map(p=>`<div class="modal-item"><span class="item-emoji">${p.emoji}</span><div><h3>${p.name}</h3><p>${state.inventory[p.id]} in cupboard · +${p.id==='kibble'?30:55} fullness</p></div><button class="btn" data-feed="${p.id}" ${state.inventory[p.id]<1?'disabled':''}>Serve</button></div>`).join('')}</div><button class="btn secondary full" id="food-shop">Visit the little shop ${icon('arrow')}</button>`);document.querySelectorAll('[data-feed]').forEach(b=>b.onclick=()=>{const id=b.dataset.feed;if(!state.inventory[id])return;state.inventory[id]--;add(cat(),'hunger',id==='kibble'?30:55);if(id==='salmon')add(cat(),'happiness',8);xp('feed');recover();save();$('#modal').close();render();animatePet('A full tummy and a happy heart.','♡');toast('Supper served. A very satisfied little cat.');});$('#food-shop').onclick=()=>{$('#modal').close();shopTab='food';go('shop')}}
function medicineModal(){const c=cat();modal('A little care goes a long way.',`<p class="subtitle">${c.medicated?'Medicine is already helping. Now add food, love, and rest.':'Give medicine, then bring fullness & happiness to 40 and energy to 35. Your cat can play once recovered.'}</p><div class="modal-item"><span class="item-emoji">🩹</span><div><h3>Little care kit</h3><p>${state.inventory.medicine} in cupboard · 35 coins in shop</p></div><button class="btn" id="give-medicine" ${!state.inventory.medicine||c.medicated?'disabled':''}>${c.medicated?'Given ✓':'Give'}</button></div><p class="modal-note">${c.medicated?'✓ Medicine given':'○ Medicine needed'}<br>${c.hunger>=40?'✓':'○'} Full tummy · ${Math.round(c.hunger)} / 40<br>${c.happiness>=40?'✓':'○'} Happiness · ${Math.round(c.happiness)} / 40<br>${c.energy>=35?'✓':'○'} Energy · ${Math.round(c.energy)} / 35</p><button class="btn secondary full" id="medicine-shop">Shop care kits ${icon('arrow')}</button>`);$('#give-medicine').onclick=()=>{if(!state.inventory.medicine||c.medicated)return;state.inventory.medicine--;c.medicated=true;add(c,'health',30);const cured=recover();save();$('#modal').close();render();if(!cured)toast('Medicine given. Food, love, and rest will finish recovery.');};$('#medicine-shop').onclick=()=>{$('#modal').close();shopTab='care';go('shop')}}
function buy(id){const p=products.find(p=>p.id===id);if(p.kind==='accessories'&&state.owned.includes(id)){cat().accessory=id;save();render();return toast(`${cat().name} is wearing the ${p.name.toLowerCase()}.`)}if(state.coins<p.price)return toast('A little more play first! Earn coins in the minigames.');state.coins-=p.price;if(p.kind==='accessories'){state.owned.push(id);cat().accessory=id}else state.inventory[id]++;save();render();toast(`${p.name} ${p.kind==='accessories'?'purchased & equipped':'added to your cupboard'}.`)}
function checkin(){if(state.lastCheckin===today())return;const yesterday=new Date();yesterday.setDate(yesterday.getDate()-1);state.streak=state.lastCheckin===yesterday.toLocaleDateString('en-CA')?state.streak+1:1;state.lastCheckin=today();state.stamps++;let reward=40+(state.stamps%5===0?100:0);state.coins+=reward;save();render();modal('You make this place feel like home.',`<div class="reward-big">☕</div><div class="center"><h3>+${reward} coins · A little welcome back.</h3><p class="subtitle">${state.streak} day streak · ${state.stamps} digital paw stamp${state.stamps===1?'':'s'}<br>${state.stamps%5===0?'Five little visits! Your 100 coin bonus is included.':'Another little moment together.'}</p><button class="btn" id="checkin-done">Time with my companion ${icon('heart')}</button></div>`);$('#checkin-done').onclick=()=>{$('#modal').close();go('home')}}
function editCat(i){const c=state.cats[i];modal('Meet your little resident.',`<p class="subtitle">Sample profiles can become your real café cats later.</p><form id="profile-form"><label class="field-label" for="cat-name">Cat’s name</label><input id="cat-name" maxlength="24" required value="${esc(c.name)}"><label class="field-label" for="cat-bio">A little personality</label><input id="cat-bio" maxlength="90" required value="${esc(c.bio)}"><label class="field-label" for="cat-coat">Illustration coat</label><select id="cat-coat">${[['ginger','Golden ginger'],['tuxedo','Charcoal tuxedo'],['gray','Soft gray']].map(([v,l])=>`<option value="${v}" ${c.coat===v?'selected':''}>${l}</option>`).join('')}</select><label class="field-label" for="cat-photo">Profile photo (optional · stays on this device)</label><input type="file" id="cat-photo" accept="image/png,image/jpeg,image/webp"><p class="demo-note">The 3D room uses your chosen coat; your photo appears on the resident card.</p><button class="btn full" type="submit" style="margin-top:20px">Save resident</button></form>`);$('#profile-form').onsubmit=async e=>{e.preventDefault();const name=$('#cat-name').value.trim(),bio=$('#cat-bio').value.trim();if(!name||!bio)return toast('Add a name and a little personality.');const coat=$('#cat-coat').value;const file=$('#cat-photo').files[0];let photo=c.photo;if(file){if(file.size>5*1024*1024)return toast('Choose a photo under 5 MB.');try{photo=await resizePhoto(file)}catch{return toast('That image couldn’t be opened. Try a JPG or PNG.')}}Object.assign(c,{name,bio,coat,photo});save();$('#modal').close();render();toast('Your little resident’s profile is saved.')}}
async function resizePhoto(file){return new Promise((resolve,reject)=>{const url=URL.createObjectURL(file),img=new Image();img.onload=()=>{const canvas=document.createElement('canvas');canvas.width=480;canvas.height=480;const ctx=canvas.getContext('2d');const size=Math.min(img.width,img.height);ctx.drawImage(img,(img.width-size)/2,(img.height-size)/2,size,size,0,0,480,480);URL.revokeObjectURL(url);resolve(canvas.toDataURL('image/jpeg',.8))};img.onerror=()=>{URL.revokeObjectURL(url);reject()};img.src=url})}
function help(){modal('The art of a happy little cat.',`<p class="subtitle">A few small moments make all the difference.</p>${[['switch','Make yourself at home.','Drag the room with your mouse or one finger to look around. Stroke up and down over the cat for purrs and happiness. Turn Sound on to hear the purr. Scroll to zoom; arrow keys rotate the camera.'],['heart','Share the love.','Pet your cat, fill their bowl, play with the feather, and let them rest. Daily care goals earn a bonus 30 coins.'],['clock','Come back a little each day.','Fullness falls 4 points per hour, happiness 2.8, and energy 1.7—even while you’re away. At 15 fullness or 10 happiness, your cat gets sick.'],['health','A little care to feel better.','Sick cats need a 35-coin medicine kit, then at least 40 fullness, 40 happiness, and 35 energy. Play with the cat unlocks after recovery.'],['game','There’s always a way to earn.','Purrfect pairs pays 35 coins. Treat catcher pays 3 per catch, up to 60. Both stay open while your cat is sick.'],['cup','Make a little daily ritual.','Collect a daily digital stamp and 40 coins in The café. Every fifth stamp adds 100 bonus coins.']].map(([ico,t,desc])=>`<div class="help-step">${icon(ico)}<div><strong>${t}</strong><br>${desc}</div></div>`).join('')}<div class="divider"></div><h3>Try the recovery story</h3><p class="demo-note">Advance this cat’s care needs by 24 hours to try the sickness mechanic. This only changes your local prototype.</p><button class="btn secondary full" id="demo-neglect" style="margin-top:12px">Simulate 24 hours away</button><p class="demo-note">Progress is stored in this browser. This prototype has no accounts, real purchases, verified visits, or shared café records.</p>`);$('#demo-neglect').onclick=()=>{cat().lastUpdate-=24*3600000;decay(cat());save();$('#modal').close();go('home');toast('24 hours later… your companion needs a little care.')}}
function startGame(type){game=null;if(type==='memory')startMemory();else startCatch()}
function startMemory(){const items=['🐟','🎀','☕','🧶','🐾','🌿'];const cards=[...items,...items];for(let i=cards.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[cards[i],cards[j]]=[cards[j],cards[i]]}game={type:'memory',cards,open:[],matched:[],moves:0,locked:false,finished:false};modal('Purrfect pairs.',`<p class="subtitle">Find all six pairs. Take your time, little explorer.</p><div class="game-status"><span id="pair-progress">0 / 6 pairs</span><span id="moves">0 moves</span></div><div class="memory-grid">${cards.map((_,i)=>`<button class="memory-card" data-card="${i}" aria-label="Reveal card ${i+1}">✦</button>`).join('')}</div><p class="modal-note center">Match all the pairs to earn 35 coins.</p>`);document.querySelectorAll('[data-card]').forEach(b=>b.onclick=()=>flipCard(+b.dataset.card))}
function flipCard(i){const g=game;if(!g||g.type!=='memory'||g.locked||g.finished||g.open.includes(i)||g.matched.includes(i))return;const el=$(`[data-card="${i}"]`);el.textContent=g.cards[i];el.classList.add('face');el.setAttribute('aria-label',g.cards[i]);g.open.push(i);if(g.open.length<2)return;g.moves++;$('#moves').textContent=`${g.moves} moves`;const [a,b]=g.open;if(g.cards[a]===g.cards[b]){g.matched.push(a,b);g.open=[];[a,b].forEach(n=>{$(`[data-card="${n}"]`).classList.add('matched');$(`[data-card="${n}"]`).disabled=true});$('#pair-progress').textContent=`${g.matched.length/2} / 6 pairs`;if(g.matched.length===12){g.finished=true;setTimeout(()=>{if(game===g&&$('#modal').open)finishGame(35,`Six perfect pairs in ${g.moves} moves.`)},450)}}else{g.locked=true;setTimeout(()=>{if(game!==g||!$('#modal').open)return;[a,b].forEach(n=>{const b=$(`[data-card="${n}"]`);b.textContent='✦';b.classList.remove('face');b.setAttribute('aria-label',`Reveal card ${n+1}`)});g.open=[];g.locked=false},750)}}
function startCatch(){game={type:'catch',score:0,started:false,finished:false};modal('Treat catcher.',`<p class="subtitle">Catch the treats as they pop up. Each catch earns 3 coins.</p><div class="game-status"><span id="catch-score">0 treats caught</span><span id="catch-time">20 seconds</span></div><div class="catch-board" id="catch-board"><div class="catch-start"><span>🥣</span><p>Tap treats with your mouse, finger, or Enter.</p><button class="btn" id="catch-start">Ready, set, paws!</button></div></div><p class="modal-note center">20 seconds · Up to 60 coins · No energy needed</p>`);$('#catch-start').onclick=runCatch}
function runCatch(){const g=game;if(!g||g.started)return;g.started=true;g.end=Date.now()+20000;$('#catch-board').innerHTML='<button class="catch-target" id="catch-target" aria-label="Catch treat">🐟</button>';moveTreat();$('#catch-target').focus();$('#catch-target').onclick=()=>{if(game!==g||g.finished)return;if(Date.now()>=g.end)return finishCatch(g);g.score++;$('#catch-score').textContent=`${g.score} treats caught`;if(g.score>=20)return finishCatch(g);moveTreat()};gameTimer=setInterval(()=>{if(game!==g||!$('#modal').open)return clearInterval(gameTimer);$('#catch-time').textContent=`${Math.max(0,Math.ceil((g.end-Date.now())/1000))} seconds`;if(Date.now()>=g.end)finishCatch(g)},150)}
function moveTreat(){const board=$('#catch-board'),target=$('#catch-target');if(!target)return;target.style.left=`${10+Math.random()*(board.clientWidth-78)}px`;target.style.top=`${10+Math.random()*(board.clientHeight-78)}px`;target.textContent=['🐟','🍪','🦐'][Math.floor(Math.random()*3)]}
function finishCatch(g){if(g.finished)return;g.finished=true;clearInterval(gameTimer);finishGame(g.score*3,`${g.score} treats caught. Those are some quick paws!`)}
function finishGame(reward,desc){if(!game||game.rewarded)return;game.rewarded=true;state.coins+=reward;state.games++;save();render();modal('A pocketful of little rewards.',`<div class="reward-big">${reward?'✨':'🌿'}</div><div class="center"><h2>+${reward} coins</h2><p class="subtitle">${desc}<br>${reward?'Your cupboard is one step closer to full.':'A practice round! Try again whenever you like.'}</p><button class="btn" id="play-again">Another little game ${icon('game')}</button><button class="btn secondary" id="reward-close" style="margin-left:8px">Back to my cat</button></div>`);$('#play-again').onclick=()=>startGame(game.type);$('#reward-close').onclick=()=>{$('#modal').close();go('home')}}
$('#modal').addEventListener('close',()=>{clearInterval(gameTimer);game=null;cafeRoom?.setActive(page==='home')});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));$('.brand').onclick=e=>{e.preventDefault();go('home')};$('#help-button').onclick=help;$('#mobile-help').onclick=help;$('#coin-button').onclick=()=>go('shop');$('#profile-button').onclick=()=>go('cafe');
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')render()});setInterval(()=>{if(!$('#modal').open)render()},30000);render();
